class Buffer {
    int* ptr;
public:
    Buffer(size_t s) : ptr(new int[s]) {}
    ~Buffer() { delete[] ptr; }

    // Move Constructor (T(T&&))
    Buffer(Buffer&& other) noexcept
        : ptr(other.ptr) {
        other.ptr = nullptr; // Resource theft complete
    }
};

// Move Assignment Operator (T& operator=(T&&))
Buffer& operator=(Buffer&& other) noexcept {
    if (this != &other) {
        delete[] ptr;        // Release current resource
        ptr = other.ptr;     // Steal resource
        other.ptr = nullptr; // Nullify source
    }
    return *this;
}

// Function accepting an rvalue reference
void sink(std::vector<int>&& temp_vec) {
    // temp_vec is guaranteed to be an rvalue
    // Internal resources can be safely moved
}

std::vector<int> large_vec(1000);
std::vector<int> other_vec;

// Explicitly invoke move semantics
other_vec = std::move(large_vec);

// Pass to sink (consumes the resource)
sink(std::move(other_vec));
